def any_int(x, y, z):
    # Check if all numbers are integers
    if not (isinstance(x, int) and isinstance(y, int) and isinstance(z, int)):
        return False
    # Check if one equals the sum of the other two
    if x + y == z or x + z == y or y + z == x:
        return True
    return False
```

