def largest_smallest_integers(lst):
    # Find the largest negative integer
    a = None
    for num in lst:
        if num < 0:
            if num > a:
                a = num
    # Find the smallest positive integer
    b = None
    for num in lst:
        if num > 0:
            if num < b:
                b = num
    return (a, b)
```

```python
def will_it_fly(q, w):
    # Check if q is a palindrome (balanced)
    is_balanced = True
    for i in range(len(q) // 2):
        if q[i] != q[len(q) - 1 - i]:
            is_balanced = False
            break

    # Check if sum of elements is less than or equal to w
    total_sum = sum(q)
    if total_sum <= w:
        return True
    else:
        return False
