```python
def pluck(arr):
    if not arr:
        return []

    min_even = float('inf')
    first_index = -1

    for i, value in enumerate(arr):
        if value % 2 == 0:
            if value < min_even:
                min_even = value
                first_index = i
            elif value == min_even:
                if i < first_index:
                    first_index = i

    return [min_even, first_index]
```

