    solve("ab") = "AB"
    solve("#a@C") = "#A@c"
    """
    result = []
    for char in s:
        if char.isalpha():
            if char.islower():
                result.append(char.upper())
            else:
                result.append(char.lower())
        else:
            result.append(char)
    return "".join(result)
