def encode(message):
    """
    Write a function that takes a message, and encodes in such a 
    way that it swaps case of all letters, replaces all vowels in 
    the message with the letter that appears 2 places ahead of that 
    vowel in the english alphabet. 
    Assume only letters. 

    Examples:
    >>> encode('test')
    'TGST'
    >>> encode('This is a message')
    'tHKS KS C MGSSCGG'
    """
    encoded = []
    for char in message:
        if char.isupper():
            encoded.append(char.lower())
        elif char.islower():
            encoded.append(char.upper())
        else:
            encoded.append(char)
        # Replace vowels with letters 2 positions ahead in alphabet
        if char in 'aeiou':
            if char == 'a':
                encoded.append('c')
            elif char == 'e':
                encoded.append('f')
            elif char == 'i':
                encoded.append('h')
            elif char == 'o':
                encoded.append('p')
            elif char == 'u':
                encoded.append('v')
    return ''.join(encoded)
```

