        return ()
    if planet2 not in ["Mercury", "Venus", "Earth", "Mars", "Jupiter", "Saturn", "Uranus", "Neptune"]:
        return ()

    # Define the planets in order from closest to farthest
    planets = ["Mercury", "Venus", "Earth", "Mars", "Jupiter", "Saturn", "Uranus", "Neptune"]

    # Find planets between planet1 and planet2 (inclusive)
    between_planets = []
    for planet in planets:
        if planet1 <= planet <= planet2:
            between_planets.append(planet)

    # Sort by proximity to the Sun (closest first)
    between_planets.sort()

    return tuple(between_planets)
